import {gearbox} from './gearbox.mjs';
import * as T from '../vendor/three.module.js';
import {OrbitControls} from '../vendor/OrbitControls.js';
import {ratio} from './config.mjs';
const tau=Math.PI*2, m=.085, blue=0x38d7ed,gold=0xf6ae58,iron=0x637783;
function contour(n,internal=false){const r=n*m/2,s=new T.Shape();for(let i=0;i<n;i++)for(const [j,h] of [[-.5,-.95],[-.34,-.95],[-.17,.85],[.17,.85],[.34,-.95]]){const a=tau*(i+j)/n,d=r+h*m*(internal?-1:1);s[s.curves.length===0&&i===0&&j===-.5?'moveTo':'lineTo'](d*Math.cos(a),d*Math.sin(a))}s.closePath();return s}
function circle(r,x=0,y=0){const p=new T.Path();p.absarc(x,y,r,0,tau,true);return p}
export function bench(host){
 const scene=new T.Scene(),renderer=new T.WebGLRenderer({antialias:true,alpha:true});host.append(renderer.domElement);renderer.setPixelRatio(Math.min(devicePixelRatio,2));const cam=new T.OrthographicCamera(-4,4,3,-3,.1,100);cam.position.set(3,-4,10);const orbit=new OrbitControls(cam,renderer.domElement);orbit.enablePan=false;orbit.minZoom=.65;orbit.maxZoom=2.8;orbit.enableZoom=false;
 scene.add(new T.HemisphereLight(0xe6ffff,0x45556e,2));for(const [x,y,z,n] of [[-4,6,7,3],[5,-2,5,2]]){let l=new T.DirectionalLight(0xffffff,n);l.position.set(x,y,z);scene.add(l)}
 let anchor=null;const marker=document.createElement("span");marker.className="shift-marker";host.append(marker);const projected=new T.Vector3();let root=new T.Group(),turn=[],fit=6.5;scene.add(root);
 function mesh(geometry,color,parent,x=0,y=0,z=0){const o=new T.Mesh(geometry,new T.MeshStandardMaterial({color,metalness:.48,roughness:.29}));parent.add(o);o.position.set(x,y,z);return o}
 function support(x,y,top){pin(root,x,y,-1.10,.32,.12);pin(root,x,y,(top-1.08)/2,.12,top+1.08);pin(root,x,y,top-.08,.24,.15)}
 function pin(parent,x,y,z,r,h,c=iron){const g=new T.CylinderGeometry(r,r,h,32);g.rotateX(Math.PI/2);return mesh(g,c,parent,x,y,z)}
 function box(parent,x,y,z,a,b,c,color){return mesh(new T.BoxGeometry(a,b,c),color,parent,x,y,z)}
 function band(parent,x,y,z,r,t,color){return mesh(new T.TorusGeometry(r,t,6,64),color,parent,x,y,z)}
 function gear(n,x,y,z,color,speed,offset=0,parent=root,ring=false){const g=new T.Group();parent.add(g);g.position.set(x,y,z);const r=n*m/2;let s=contour(n);if(ring){s=new T.Shape();s.absarc(0,0,r+.26,0,tau,false);s.holes.push(contour(n,true))}else{s.holes.push(circle(.13));if(r>.6)for(let i=0;i<5;i++)s.holes.push(circle(r*.14,r*.6*Math.cos(i*tau/5),r*.6*Math.sin(i*tau/5)))}const e=new T.ExtrudeGeometry(s,{depth:.22,bevelEnabled:true,bevelSize:.014,bevelThickness:.016,bevelSegments:2,curveSegments:10});mesh(e,color,g);pin(g,ring?r+.14:r*.81,0,.24,.046,.025,0xf2f7eb);if(ring)band(g,0,0,.235,r+.21,.022,0xaabcc6);else {band(g,0,0,.24,.20,.026,0xbdcdd1);band(g,0,0,.222,r-.11,.012,color)}if(!ring){pin(g,0,0,.245,.18,.09,iron);pin(g,0,0,.3,.085,.03,0xccdce1)}turn.push(a=>g.rotation.z=offset+a*speed);return g}
 function setup(k,v,{step=7,apart=false}={}){anchor=null;marker.hidden=k!==5;scene.remove(root);root.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});root=new T.Group();scene.add(root);turn=[];let q=ratio(k,v),r=n=>n*m/2;
 if(k===4){support(0,0,.08);gear(18,0,0,.08,blue,1);gear(54,0,0,.08,v?gold:iron,v?q:0,0,root,true);let carrier=new T.Group();root.add(carrier);const c=v?0:q;turn.push(a=>carrier.rotation.z=c*a);for(let i=0;i<3;i++){const a=i*tau/3,x=2*r(18)*Math.cos(a),y=2*r(18)*Math.sin(a);gear(18,x,y,.08,iron,-(1-c),Math.PI/18,carrier);let arm=box(carrier,x/2,y/2,.51,2*r(18),.13,.10,v?iron:gold);arm.rotation.z=a;pin(carrier,x,y,.53,.13,.12); }pin(carrier,0,0,.56,.22,.18,v?iron:gold)}
 else if(k===5){anchor=gearbox({root,gear,pin,box,band,mesh,turn,T},v,step,apart);cam.position.set(6,4,2.2);cam.lookAt(0,0,-.45);orbit.target.set(0,0,-.45);cam.zoom=1;fit=apart?9.5:7.8;resize();return}
 else if(k===0){support(0,0,0);gear([18,36,54][v],0,0,0,blue,1);const rad=r([18,36,54][v]);root.add(new T.ArrowHelper(new T.Vector3(0,1,0),new T.Vector3(rad,0,.37),1.52/(v+1),gold,.23,.13))}
 else {let n=k===1?[18,36,54][v]:k===2?[12,18,24][v]:36;const d=r(18+n),e=k===2?r(n+36):k===3?r(12+[24,36][v]):0;const x=-(d+e)/2;support(x,0,0);support(x+d,0,0);if(e)support(x+d+e,0,k===3?.64:0);gear(18,x,0,0,blue,1);gear(n,x+d,0,0,k===1?gold:iron,-18/n,Math.PI/n);if(k===2)gear(36,x+d+e,0,0,gold,q);if(k===3){pin(root,x+d,0,.38,.14,.8);gear(12,x+d,0,.64,iron,-.5);gear([24,36][v],x+d+e,0,.64,gold,q,Math.PI/[24,36][v])}}
 if(k!==5)cam.position.set(2.4,-4,10);cam.lookAt(0,0,0);orbit.target.set(0,0,0);cam.zoom=1;fit=k===2||k===3?8:6.4;
 const w=k===2||k===3?7:5.8;box(root,0,0,-1.24,w,5.4,.17,0x233442);for(let j=-10;j<=10;j++)box(root,j*w/24,-2.45,-1.145,.018,j%5===0?.22:.10,.012,0x99acb3);for(const x of [-1,1])for(const y of [-1,1]){pin(root,x*(w/2-.25),y*2.43,-1.12,.095,.08);box(root,x*(w/2-.25),y*2.43,-1.071,.10,.019,.01,0x152029)}resize()}
 function resize(){let w=host.clientWidth||1,h=host.clientHeight||1,a=w/h,span=Math.max(fit/a,5.9);cam.left=-span*a/2;cam.right=-cam.left;cam.top=span/2;cam.bottom=-cam.top;cam.updateProjectionMatrix();renderer.setSize(w,h,false)}
 new ResizeObserver(resize).observe(host);return {setup,label(text){marker.textContent=text},view(front,k){cam.position.set(...(front?[0,0,11]:k===5?[6,4,2.2]:[2.4,-4,10]));cam.lookAt(0,0,0);orbit.update()},draw(a){turn.forEach(f=>f(a));orbit.update();renderer.render(scene,cam);if(anchor){projected.copy(anchor).project(cam);marker.style.left=(projected.x+1)*50+"%";marker.style.top=(1-projected.y)*50+"%"}}}
}
